tool_input.command:
cat >> db/schema.ts <<'E'

export const comments = sqliteTable(
  'comments',
  {
    id: integer('id').primaryKey({ autoIncrement: true }),
    postId: integer('post_id')
      .notNull()
      .references(() => posts.id, { onDelete: 'cascade' }),
    userId: integer('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    body: text('body').notNull(),
    createdAt: text('created_at').notNull().$defaultFn(() => new Date().toISOString()),
  },
  (table) => [index('comments_post_id_idx').on(table.postId)],
)
E
sed -i.bak "1s/.*/import { sqliteTable, integer, text, index } from '@guren\/orm\/drizzle\/sqlite'/" db/schema.ts && rm db/schema.ts.bak
grep -rn "index" node_modules/@guren/orm/drizzle/sqlite* 2>/dev/null | head -3
cat > app/Models/Comment.ts <<'E'
import { defineModel, type BelongsToRecord } from '@guren/core'
import { comments } from '../../db/schema.js'
import type { PostRecord } from './Post.js'
import type { UserRecord } from './User.js'

export type CommentRecord = typeof comments.$inferSelect
export type CommentAuthorSummary = Pick<UserRecord, 'id' | 'name'>

export class Comment extends defineModel(comments, {
  // `postId` and `userId` come from the path and the session, never from request input.
  fillable: ['body'],
}) {
  static override relationTypes: {
    post: BelongsToRecord<PostRecord>
    author: BelongsToRecord<CommentAuthorSummary>
  } = { post: null, author: null }
}

Comment.belongsTo('post', () => import('./Post.js').then((module) => module.Post), 'postId', 'id')
Comment.belongsTo('author', () => import('./User.js').then((module) => module.User), 'userId', 'id')
E
